    47→    let ret: u64;
    48→    unsafe {
    49→        asm!(
    50→            "syscall",
    51→            in("rax") n,
    52→            in("rdi") arg1,
    53→            lateout("rax") ret,
    54→            lateout("rcx") _,
    55→            lateout("r11") _,
    56→            options(nostack)
    57→        );
