   300→#[unsafe(no_mangle)]
   301→extern "C" fn rust_eh_personality() {}
   302→
   303→unsafe extern "Rust" {
   304→    safe fn main();
   305→}
   306→
   307→extern "C" fn _start_rust() -> ! {
   308→    init_heap();
   309→    main();
   310→    exit(0)
   311→}
   312→
   313→#[unsafe(no_mangle)]
   314→#[unsafe(naked)]
   315→pub extern "C" fn _start() -> ! {
   316→    // Kernel enters with RSP aligned to 16 bytes, pointing to argc
   317→    // call pushes 8-byte return address, so callee sees RSP % 16 == 8
   318→    core::arch::naked_asm!(
   319→        "mov rbx, rsp",               // save original RSP (points to argc)
   320→        "mov rdi, [rbx]",             // rdi = argc
   321→        "lea rsi, [rbx + 8]",         // rsi = argv
   322→        "lea rdx, [rsi + rdi*8 + 8]", // rdx = envp
   323→        "call {start_rust}",
   324→        "ud2",
   325→        start_rust = sym _start_rust,
   326→    );
   327→}
