   162→/// # Safety
   163→/// Caller must ensure `n` is a valid syscall number and all arguments
   164→/// are valid for that syscall.
   165→#[inline(always)]
   166→pub unsafe fn syscall6(
   167→    n: u64,
   168→    arg1: u64,
   169→    arg2: u64,
   170→    arg3: u64,
   171→    arg4: u64,
   172→    arg5: u64,
   173→    arg6: u64,
   174→) -> u64 {
   175→    let ret: u64;
   176→    unsafe {
   177→        asm!(
   178→            "syscall",
   179→            in("rax") n,
   180→            in("rdi") arg1,
   181→            in("rsi") arg2,
   182→            in("rdx") arg3,
   183→            in("r10") arg4,
   184→            in("r8") arg5,
   185→            in("r9") arg6,
   186→            lateout("rax") ret,
   187→            lateout("rcx") _,
   188→            lateout("r11") _,
   189→            options(nostack)
   190→        );
   191→    }
   192→    ret
   193→}
   194→
   195→// --- Public API ---
   196→
   197→pub fn exit(code: i32) -> ! {
   198→    unsafe {
   199→        syscall1(SYS_EXIT, code as u64);
   200→        asm!("ud2", options(noreturn));
   201→    }
   202→}
   203→
   204→/// Write bytes to a file descriptor.
   205→///
   206→/// # Safety
   207→/// `buf` must point to at least `count` valid bytes.
   208→#[unsafe(no_mangle)]
   209→pub unsafe extern "C" fn write(fd: i32, buf: *const u8, count: usize) -> isize {
   210→    unsafe { syscall3(SYS_WRITE, fd as u64, buf as u64, count as u64) as isize }
   211→}
   212→
   213→/// Read bytes from a file descriptor.
   214→///
   215→/// # Safety
   216→/// `buf` must point to at least `count` bytes of writable memory.
   217→#[unsafe(no_mangle)]
   218→pub unsafe extern "C" fn read(fd: i32, buf: *mut u8, count: usize) -> isize {
   219→    unsafe { syscall3(SYS_READ, fd as u64, buf as u64, count as u64) as isize }
   220→}
   221→
   222→fn brk(addr: *mut u8) -> *mut u8 {
   223→    unsafe { syscall1(SYS_BRK, addr as u64) as *mut u8 }
   224→}
   225→
   226→fn init_heap() {
   227→    unsafe {
   228→        HEAP_START = brk(core::ptr::null_mut());
   229→        HEAP_END = HEAP_START;
   230→        HEAP_CURRENT = HEAP_START;
   231→    }
   232→}
   233→
   234→#[unsafe(no_mangle)]
   235→pub extern "C" fn malloc(size: usize) -> *mut u8 {
   236→    unsafe {
   237→        let aligned_size = (size + 15) & !15;
   238→        let new_current = HEAP_CURRENT.add(aligned_size);
   239→
   240→        if new_current > HEAP_END {
   241→            let grow_size = (aligned_size + 4095) & !4095;
   242→            let new_end = brk(HEAP_END.add(grow_size));
   243→            if new_end <= HEAP_END {
   244→                return core::ptr::null_mut();
   245→            }
   246→            HEAP_END = new_end;
   247→        }
   248→
   249→        let ptr = HEAP_CURRENT;
   250→        HEAP_CURRENT = new_current;
   251→        ptr
   252→    }
   253→}
   254→
   255→/// Reallocate memory.
   256→///
   257→/// # Safety
   258→/// If `ptr` is non-null, it must have been returned by a previous call to
   259→/// `malloc`, `realloc`, or `calloc`, and `size` must not exceed the original
   260→/// allocation size (this simple allocator doesn't track sizes).
   261→#[unsafe(no_mangle)]
   262→pub unsafe extern "C" fn realloc(ptr: *mut u8, size: usize) -> *mut u8 {
   263→    if ptr.is_null() {
   264→        return malloc(size);
   265→    }
   266→    let new_ptr = malloc(size);
   267→    if !new_ptr.is_null() {
   268→        unsafe {
   269→            core::ptr::copy_nonoverlapping(ptr, new_ptr, size);
   270→        }
   271→    }
   272→    new_ptr
   273→}
   274→
   275→#[unsafe(no_mangle)]
   276→pub extern "C" fn calloc(nmemb: usize, size: usize) -> *mut u8 {
   277→    let total = nmemb.saturating_mul(size);
   278→    let ptr = malloc(total);
   279→    if !ptr.is_null() {
   280→        unsafe {
   281→            core::ptr::write_bytes(ptr, 0, total);
   282→        }
   283→    }
   284→    ptr
   285→}
   286→
   287→#[unsafe(no_mangle)]
   288→pub extern "C" fn free(_ptr: *mut u8) {
   289→    // Simple bump allocator doesn't free individual allocations
   290→}
   291→
   292→// --- Runtime ---
   293→
   294→#[cfg(not(test))]
   295→#[panic_handler]
   296→fn panic(_info: &PanicInfo) -> ! {
   297→    exit(101)
   298→}
   299→
   300→#[unsafe(no_mangle)]
   301→extern "C" fn rust_eh_personality() {}
   302→
   303→unsafe extern "Rust" {
   304→    safe fn main();
   305→}
   306→
   307→extern "C" fn _start_rust() -> ! {
   308→    init_heap();
   309→    main();
   310→    exit(0)
   311→}
   312→
   313→#[unsafe(no_mangle)]
   314→#[unsafe(naked)]
   315→pub extern "C" fn _start() -> ! {
   316→    // Kernel enters with RSP aligned to 16 bytes, pointing to argc
   317→    // call pushes 8-byte return address, so callee sees RSP % 16 == 8
   318→    core::arch::naked_asm!(
   319→        "mov rbx, rsp",               // save original RSP (points to argc)
   320→        "mov rdi, [rbx]",             // rdi = argc
   321→        "lea rsi, [rbx + 8]",         // rsi = argv
   322→        "lea rdx, [rsi + rdi*8 + 8]", // rdx = envp
   323→        "call {start_rust}",
   324→        "ud2",
   325→        start_rust = sym _start_rust,
   326→    );
   327→}
