   109→/// Invoke a syscall with 4 arguments.
   110→///
   111→/// # Safety
   112→/// Caller must ensure `n` is a valid syscall number and all arguments
   113→/// are valid for that syscall.
   114→#[inline(always)]
   115→pub unsafe fn syscall4(n: u64, arg1: u64, arg2: u64, arg3: u64, arg4: u64) -> u64 {
   116→    let ret: u64;
   117→    unsafe {
   118→        asm!(
   119→            "syscall",
   120→            in("rax") n,
   121→            in("rdi") arg1,
   122→            in("rsi") arg2,
   123→            in("rdx") arg3,
   124→            in("r10") arg4,
   125→            lateout("rax") ret,
   126→            lateout("rcx") _,
   127→            lateout("r11") _,
   128→            options(nostack)
   129→        );
