   145→            in("rax") n,
   146→            in("rdi") arg1,
   147→            in("rsi") arg2,
   148→            in("rdx") arg3,
   149→            in("r10") arg4,
   150→            in("r8") arg5,
   151→            lateout("rax") ret,
   152→            lateout("rcx") _,
   153→            lateout("r11") _,
   154→            options(nostack)
   155→        );
   156→    }
