   161→///
   162→/// # Safety
   163→/// Caller must ensure `n` is a valid syscall number and all arguments
   164→/// are valid for that syscall.
   165→#[inline(always)]
   166→pub unsafe fn syscall6(
   167→    n: u64,
   168→    arg1: u64,
   169→    arg2: u64,
   170→    arg3: u64,
   171→    arg4: u64,
   172→    arg5: u64,
   173→    arg6: u64,
   174→) -> u64 {
   175→    let ret: u64;
   176→    unsafe {
   177→        asm!(
   178→            "syscall",
   179→            in("rax") n,
   180→            in("rdi") arg1,
   181→            in("rsi") arg2,
   182→            in("rdx") arg3,
   183→            in("r10") arg4,
   184→            in("r8") arg5,
   185→            in("r9") arg6,
   186→            lateout("rax") ret,
