    28→        asm!(
    29→            "syscall",
    30→            in("rax") n,
    31→            lateout("rax") ret,
    32→            lateout("rcx") _,
    33→            lateout("r11") _,
    34→            options(nostack)
    35→        );
    36→    }
    37→    ret
    38→}
