//! CLI commands for tspec management (cargo xt ts ...)

use anyhow::Result;
use std::path::Path;

use crate::find_paths::{find_crate_dir, find_workspace_root};
use crate::workspace::WorkspaceInfo;

/// List all *.xt.toml files in workspace or for a specific crate
pub fn list_tspecs(crate_name: Option<&str>) -> Result<()> {
    let workspace = find_workspace_root()?;

    match crate_name {
        Some(name) => {
            let crate_dir = find_crate_dir(&workspace, name)?;
            let tspecs = find_xt_toml_files(&crate_dir)?;
            print_crate_tspecs(name, &crate_dir, &tspecs);
        }
        None => {
            let info = WorkspaceInfo::discover()?;
            let mut found_any = false;

            for member in &info.members {
                let tspecs = find_xt_toml_files(&member.path)?;
                if !tspecs.is_empty() {
                    print_crate_tspecs(&member.name, &member.path, &tspecs);
                    found_any = true;
                }
            }

            if !found_any {
                println!("No *.xt.toml files found in workspace");
            }
        }
    }

    Ok(())
}

/// Find all *.xt.toml files in a directory
fn find_xt_toml_files(dir: &Path) -> Result<Vec<String>> {
    let mut files = Vec::new();

    if let Ok(entries) = std::fs::read_dir(dir) {
        for entry in entries.filter_map(|e| e.ok()) {
            let name = entry.file_name().to_string_lossy().to_string();
            if name.ends_with(".xt.toml") {
                files.push(name);
            }
        }
    }

    files.sort();
    Ok(files)
}

/// Print tspec files for a crate
fn print_crate_tspecs(crate_name: &str, crate_dir: &Path, tspecs: &[String]) {
    println!("{}:", crate_name);
    for tspec in tspecs {
        let path = crate_dir.join(tspec);
        let size = std::fs::metadata(&path)
            .map(|m| format_size(m.len()))
            .unwrap_or_else(|_| "?".to_string());
        println!("  {} ({})", tspec, size);
    }
}

/// Format file size in human-readable form
fn format_size(bytes: u64) -> String {
    if bytes < 1024 {
        format!("{} B", bytes)
    } else {
        format!("{:.1} KB", bytes as f64 / 1024.0)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn format_size_bytes() {
        assert_eq!(format_size(100), "100 B");
        assert_eq!(format_size(1023), "1023 B");
    }

    #[test]
    fn format_size_kb() {
        assert_eq!(format_size(1024), "1.0 KB");
        assert_eq!(format_size(2560), "2.5 KB");
    }
}

use clap::{Parser, Subcommand};

#[derive(Parser)]
#[command(name = "xt")]
#[command(about = "Translation spec based build system")]
pub struct Cli {
    #[command(subcommand)]
    pub command: Commands,
}

#[derive(Subcommand)]
pub enum Commands {
    /// Build crate(s) with a translation spec
    Build {
        /// Crate to build (omit for all workspace members)
        crate_name: Option<String>,
        /// Translation spec to use (defaults to crate's tspec.xt.toml)
        #[arg(short = 't', long = "tspec")]
        tspec: Option<String>,
        /// Release build
        #[arg(short, long)]
        release: bool,
        /// Strip symbols from binary after build
        #[arg(short, long)]
        strip: bool,
        /// Stop on first failure (for all-crates mode)
        #[arg(short, long)]
        fail_fast: bool,
    },
    /// Build and run crate(s) with a translation spec
    Run {
        /// Crate to run (omit for all apps)
        crate_name: Option<String>,
        /// Translation spec to use (defaults to crate's tspec.xt.toml)
        #[arg(short = 't', long = "tspec")]
        tspec: Option<String>,
        /// Release build
        #[arg(short, long)]
        release: bool,
        /// Strip symbols from binary before running
        #[arg(short, long)]
        strip: bool,
    },
    /// Test crate(s) with a translation spec
    Test {
        /// Crate to test (omit for all workspace members)
        crate_name: Option<String>,
        /// Translation spec to use (defaults to crate's tspec.xt.toml)
        #[arg(short = 't', long = "tspec")]
        tspec: Option<String>,
        /// Release build
        #[arg(short, long)]
        release: bool,
        /// Stop on first failure
        #[arg(short, long)]
        fail_fast: bool,
    },
    /// Compare specs for a crate (size only)
    Compare {
        /// Crate to compare
        crate_name: String,
        /// Spec file(s) or glob pattern(s) (defaults to tspec*.xt.toml)
        #[arg(short = 't', long = "tspec", action = clap::ArgAction::Append)]
        tspec: Vec<String>,
        /// Release build
        #[arg(short, long)]
        release: bool,
        /// Strip symbols before comparing sizes
        #[arg(short, long)]
        strip: bool,
    },
    /// Manage crate compatibility with specs
    Compat {
        /// Crate name
        crate_name: String,
        /// Spec to add to compat list (omit to show current state)
        spec: Option<String>,
    },
    /// Mark a spec as incompatible with a crate
    Incompat {
        /// Crate name
        crate_name: String,
        /// Spec to add to incompat list
        spec: String,
    },
    /// Manage translation specs (alias: ts)
    #[command(alias = "ts")]
    Tspec {
        #[command(subcommand)]
        command: TspecCommands,
    },
}

#[derive(Subcommand)]
pub enum TspecCommands {
    /// List *.xt.toml files in workspace or for a specific crate
    List {
        /// Crate to list specs for (omit for all crates)
        crate_name: Option<String>,
    },
    /// Show a spec's contents
    Show {
        /// Crate name
        crate_name: String,
        /// Spec name (defaults to tspec.xt.toml)
        #[arg(short = 't', long = "tspec")]
        tspec: Option<String>,
    },
    /// Show the content hash of a spec
    Hash {
        /// Crate name
        crate_name: String,
        /// Spec name (defaults to tspec.xt.toml)
        #[arg(short = 't', long = "tspec")]
        tspec: Option<String>,
    },
}

use serde::{Deserialize, Serialize};
use std::path::PathBuf;

/// Build profile - mutually exclusive
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Profile {
    Debug,
    Release,
}

/// Optimization level - mutually exclusive
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub enum OptLevel {
    #[serde(rename = "0")]
    O0,
    #[serde(rename = "1")]
    O1,
    #[serde(rename = "2")]
    O2,
    #[serde(rename = "3")]
    O3,
    #[serde(rename = "s")]
    Os,
    #[serde(rename = "z")]
    Oz,
}

/// Panic strategy - mutually exclusive
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum PanicStrategy {
    Abort,
    Unwind,
    /// Nightly only: -C panic=immediate-abort (eliminates panic formatting)
    ImmediateAbort,
}

/// Cargo-specific parameters
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum CargoParam {
    Profile(Profile),
    TargetTriple(String),
    TargetJson(PathBuf),
    /// Nightly-only -Z flag (e.g., "panic-immediate-abort")
    Unstable(String),
}

/// Rustc codegen and compilation parameters
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum RustcParam {
    OptLevel(OptLevel),
    Panic(PanicStrategy),
    Lto(bool),
    CodegenUnits(u32),
    /// Crates to rebuild with -Z build-std (nightly only)
    BuildStd(Vec<String>),
    /// Raw flag passed through
    Flag(String),
}

/// Version script configuration for symbol visibility
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct VersionScript {
    /// Symbols to keep global (e.g., ["_start"])
    pub global: Vec<String>,
    /// Pattern for local symbols (typically "*")
    #[serde(default = "default_local")]
    pub local: String,
}

fn default_local() -> String {
    "*".to_string()
}

/// Linker parameters
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum LinkerParam {
    /// Linker arguments from tspec.toml
    Args(Vec<String>),
    /// Version script for symbol visibility (enables --gc-sections optimization)
    VersionScript(VersionScript),
}

/// A translation spec - ordered parameter lists
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct Spec {
    #[serde(default)]
    pub cargo: Vec<CargoParam>,
    #[serde(default)]
    pub rustc: Vec<RustcParam>,
    #[serde(default)]
    pub linker: Vec<LinkerParam>,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn spec_default_is_empty() {
        let spec = Spec::default();
        assert!(spec.cargo.is_empty());
        assert!(spec.rustc.is_empty());
        assert!(spec.linker.is_empty());
    }
}

