        let libs_dir = tmp.path().join("libs").join("my-lib");
        fs::create_dir_all(&libs_dir).unwrap();
        fs::write(libs_dir.join("Cargo.toml"), "[package]\nname = \"x\"\n").unwrap();

        let found = find_crate_dir(tmp.path(), "my-lib").unwrap();
